class ConfDesglosePeriodos extends BaseConfDesglosePeriodos {

    public function obtenerFechasPeridosXIdDesglosePeriodos($iddesgloseperiodos)
    {
        return Doctrine::getTable('ConfDesglosePeriodos')->find($iddesgloseperiodos);
    }

    public function obtenerTodasLasFechasXIdPeriodoPago($idperiodostipospago)
    {
        return Doctrine_Query::create()
            ->select('cdp.*')
            ->from('ConfDesglosePeriodos cdp')
            ->where('cdp.idperiodostipospago = ?', array($idperiodostipospago))
            ->fetchArray();
